#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn pixel_data_matches_size() {
        assert_eq!(PIXELS.len(), W * H);
        assert_eq!(H % 2, 0);
        assert!(PIXELS.iter().any(|&p| p == TRANSPARENT));
        assert!(PIXELS.iter().all(|&p| p == TRANSPARENT || p <= 0xFF_FFFF));
    }
}
